mapper.insert:
/* AuthGroupMapper.insertAuthGroup 권한그룹을 등록 */
INSERT INTO TB_AUTH_GRP_M (
    USR_GRP_CD, USR_GRP_NM, USE_YN, ST_DT, END_DT, RMK,
    FIRS_REGR_ID, FIRS_REG_DT, FINA_REGR_ID, FINA_REG_DT
) VALUES (
    #{item.usrGrpCd}, #{item.usrGrpNm}, #{item.useYn},
    NULLIF(#{item.stDt}, ''), NULLIF(#{item.endDt}, ''), NULLIF(#{item.rmk}, ''),
    #{regrId}, CURRENT_TIMESTAMP, #{regrId}, CURRENT_TIMESTAMP
)

mapper.delete:
/* AuthGroupMapper.deleteAuthGroup 권한그룹을 삭제 */
DELETE FROM TB_AUTH_GRP_M
 WHERE USR_GRP_CD = #{usrGrpCd}

/* AuthGroupMapper.deleteAuthGroupUserList 권한그룹의 사용자 매핑을 모두 삭제 (그룹 삭제 시) */
DELETE FROM TB_USR_AUTH_GRP_R
 WHERE USR_GRP_CD = #{usrGrpCd}

mapper.select:
/* AuthGroupMapper.selectAuthGroupMenuList 권한그룹의 화면 권한 목록을 메뉴ID 순으로 조회 */
SELECT USR_GRP_CD, MENU_ID, PRGM_ID
FROM TB_AUTH_GRP_MENU_R
WHERE USR_GRP_CD = #{usrGrpCd}
ORDER BY MENU_ID, PRGM_ID

mapper.insert:
/* AuthGroupMapper.insertAuthGroupMenu 권한그룹 화면 권한을 등록 (이미 있으면 건너뜀) */
INSERT INTO TB_AUTH_GRP_MENU_R (
    USR_GRP_CD, MENU_ID, PRGM_ID,
    FIRS_REGR_ID, FIRS_REG_DT, FINA_REGR_ID, FINA_REG_DT
) VALUES (
    #{item.usrGrpCd}, #{item.menuId}, #{item.prgmId},
    #{regrId}, CURRENT_TIMESTAMP, #{regrId}, CURRENT_TIMESTAMP
)
ON CONFLICT (USR_GRP_CD, MENU_ID, PRGM_ID) DO NOTHING

mapper.delete:
/* AuthGroupMapper.deleteAuthGroupMenu 권한그룹 화면 권한을 삭제 */
DELETE FROM TB_AUTH_GRP_MENU_R
 WHERE USR_GRP_CD = #{usrGrpCd}
   AND MENU_ID    = #{menuId}
   AND PRGM_ID    = #{prgmId}

/* AuthGroupMapper.deleteAuthGroupMenuList 권한그룹의 화면 권한을 모두 삭제 (그룹 삭제 시) */
DELETE FROM TB_AUTH_GRP_MENU_R
 WHERE USR_GRP_CD = #{usrGrpCd}

mapper.select:
/* AuthGroupMapper.selectAuthGroupComponentList 권한그룹의 컴포넌트 권한을 조회 (프로그램ID가 없으면 전체) */
SELECT USR_GRP_CD, PRGM_ID, CMPN_ID, AUTH_YN
FROM TB_AUTH_GRP_CMPN_R
WHERE USR_GRP_CD = #{usrGrpCd}

  AND PRGM_ID = #{prgmId}

ORDER BY PRGM_ID, CMPN_ID

mapper.delete:
/* AuthGroupMapper.deleteAuthGroupComponentList 권한그룹의 컴포넌트 권한을 모두 삭제 (그룹 삭제 시) */
DELETE FROM TB_AUTH_GRP_CMPN_R
 WHERE USR_GRP_CD = #{usrGrpCd}

/* AuthGroupMapper.deleteAuthGroupComponentWithoutMenu 화면 권한이 남아 있지 않은 프로그램의 컴포넌트 권한을 삭제 */
DELETE FROM TB_AUTH_GRP_CMPN_R C
 WHERE C.USR_GRP_CD = #{usrGrpCd}
   AND NOT EXISTS (
        SELECT 1 FROM TB_AUTH_GRP_MENU_R M
         WHERE M.USR_GRP_CD = C.USR_GRP_CD
           AND M.PRGM_ID    = C.PRGM_ID
   )

mapper.insert:
/* AuthGroupMapper.insertAuthGroupUser 권한그룹에 사용자를 추가 (이미 있으면 무시, 사용기간 오늘~99991231) */
INSERT INTO TB_USR_AUTH_GRP_R (
    USR_ID, USR_GRP_CD, ST_DT, END_DT,
    FIRS_REGR_ID, FIRS_REG_DT, FINA_REGR_ID, FINA_REG_DT
) VALUES (
    #{usrId}, #{usrGrpCd}, TO_CHAR(CURRENT_DATE, 'YYYYMMDD'), '99991231',
    #{regrId}, CURRENT_TIMESTAMP, #{regrId}, CURRENT_TIMESTAMP
)
ON CONFLICT (USR_ID, USR_GRP_CD) DO NOTHING

mapper.delete:
/* AuthGroupMapper.deleteAuthGroupUser 권한그룹에서 사용자를 제외 */
DELETE FROM TB_USR_AUTH_GRP_R
 WHERE USR_GRP_CD = #{usrGrpCd}
   AND USR_ID     = #{usrId}
